# Source: experiments/streets/stage5/editable_input/coupled_join_nodes.py
# Source SHA256: b924c8fe3a8b60242af8fc585eda9d51728dfe0c809fd0e4347314a78c88f150
"""Share a locally skewed mouth between a tight exact bend and its junction.

The adjustment translates points only along the incoming straight Section.
Its crown line and opposite half stay fixed.  The eligible inner boundary has
a straight tail after its circular corner, so neither the radius nor the
circle's actual vertices change.  The companion strip applies the same mouth
shift and fades it to zero at the first bend.  No vertices/faces are added.

This is intentionally a bounded repair, not permission to accept arbitrary
folds.  If its analytic room/Jacobian tests fail, the shift stays zero and the
normal Section validity checks report the unresolved geometry.
"""


def _smoothstep(g, value):
    x = g.math('MINIMUM', 1., g.math('MAXIMUM', 0., value))
    return g.math('MULTIPLY', g.math('MULTIPLY', x, x),
                  g.math('SUBTRACT', 3., g.math('MULTIPLY', 2., x)))


def construct(g, sources, paths, junctions, mouths):
    """Return adapted junction geometry and matching enriched mouth records.

    Required extra mouth fields: ``st_mouth_clearance_left`` and
    ``st_mouth_clearance_right`` are distances from the current mouth to each
    actual circular tangency, in the *outward* frame.  Outputs add ``shift``,
    ``side`` (+1 outward right / -1 left), ``blend_length``, ``residual`` and
    ``adapted`` under the same ``st_mouth_`` prefix.
    """
    index = g.node('GeometryNodeInputIndex', 'Coupled mouth sample index').outputs[0]
    position = g.node('GeometryNodeInputPosition', 'Unmodified junction point').outputs[0]
    for name, kind, value in [('shift', 'FLOAT', 0.), ('side', 'FLOAT', 0.),
                              ('blend_length', 'FLOAT', 0.), ('residual', 'FLOAT', 0.),
                              ('adapted', 'BOOLEAN', False)]:
        mouths = g.store(mouths, 'st_mouth_'+name, value, kind)
    size = g.node('GeometryNodeAttributeDomainSize', 'One coupled check per member mouth')
    size.component = 'MESH'
    g.set(mouths, size.inputs['Geometry'])
    ri = g.node('GeometryNodeRepeatInput', 'Adapt eligible tight bend mouths')
    ro = g.node('GeometryNodeRepeatOutput', 'Shared skew mouths and unchanged circle boundaries')
    ro.repeat_items.clear()
    for name in ('Geometry', 'Mouths'):
        ro.repeat_items.new('GEOMETRY', name)
    ri.pair_with_output(ro)
    g.set(size.outputs['Point Count'], ri.inputs['Iterations'])
    g.set(junctions, ri.inputs['Geometry'])
    g.set(mouths, ri.inputs['Mouths'])
    iteration = ri.outputs['Iteration']

    def mouth(name, kind='FLOAT'):
        return g.sample(mouths, g.named('st_mouth_'+name, kind), iteration, kind)

    sid = mouth('section_id', 'INT')
    path_index = g.stat(paths, g.switch(
        g.compare(g.named('st_path_id'), sid, kind='INT'), -1, index), output='Max')

    def path(name, kind='INT'):
        return g.sample(paths, g.named('st_path_'+name, kind), path_index, kind)

    start, npoints = path('start'), path('count')
    end = mouth('end', 'INT')
    last = g.math('SUBTRACT', npoints, 1.)
    endpoint_index = g.math('ADD', start, g.switch(end, 0., last))
    endpoint = g.sample(sources, position, endpoint_index, 'FLOAT_VECTOR')
    tangent = mouth('tangent', 'FLOAT_VECTOR')
    right = g.right(tangent)
    width = mouth('width')
    halfwidth = g.math('MULTIPLY', .5, width)
    mode = g.sample(sources, g.named('st_interpolation'), path('edge'), 'INT', 'EDGE')
    source_offset = g.sample(sources, g.named('st_offset', 'FLOAT'), path('edge'), 'FLOAT', 'EDGE')
    offset = g.switch(end, source_offset, g.math('MULTIPLY', -1., source_offset))

    # Ignore only redundant, monotonically advancing samples on the terminal
    # ray.  The first bend itself remains a mandatory authored mesh row.
    controls = g.node('GeometryNodeMeshLine', 'Bounded lookahead for the first actual bend')
    g.set(g.math('MINIMUM', 512., g.math('MAXIMUM', 2., npoints)), controls.inputs['Count'])
    rank_index = g.math('ADD', start, g.switch(end, index, g.math('SUBTRACT', last, index)))
    source_point = g.sample(sources, position, rank_index, 'FLOAT_VECTOR')
    relative = g.vector('SUBTRACT', source_point, endpoint)
    previous_rank = g.math('MAXIMUM', 0., g.math('SUBTRACT', index, 1.))
    previous_index = g.math('ADD', start, g.switch(end, previous_rank, g.math('SUBTRACT', last, previous_rank)))
    previous_point = g.sample(sources, position, previous_index, 'FLOAT_VECTOR')
    advancing = g.either(g.compare(index, 0, kind='INT'),
        g.compare(g.vector('DOT_PRODUCT', g.vector('SUBTRACT', source_point, previous_point), tangent),
                  .001, 'GREATER_THAN'))
    on_ray = g.all(advancing,
        g.compare(g.vector('LENGTH', g.vector('CROSS_PRODUCT', relative, tangent)), 1e-5, 'LESS_EQUAL'))
    first_off = g.stat(controls.outputs['Mesh'], g.switch(on_ray, index, npoints), output='Min')
    bend_rank = g.math('SUBTRACT', first_off, 1.)
    bend_index = g.math('ADD', start, g.switch(end, bend_rank, g.math('SUBTRACT', last, bend_rank)))
    next_index = g.math('ADD', bend_index, g.switch(end, 1., -1.))
    bend = g.sample(sources, position, bend_index, 'FLOAT_VECTOR')
    following = g.sample(sources, position, next_index, 'FLOAT_VECTOR')
    before_bend_index = g.math('ADD', bend_index, g.switch(end, -1., 1.))
    before_bend = g.sample(sources, position, before_bend_index, 'FLOAT_VECTOR')
    before_bend_station = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', before_bend, endpoint), tangent)
    outgoing = g.vector('NORMALIZE', g.vector('SUBTRACT', following, bend))
    denominator = g.math('ADD', 1., g.vector('DOT_PRODUCT', tangent, outgoing))
    miter = g.vector('SCALE', g.vector('ADD', right, g.right(outgoing)),
                     g.math('DIVIDE', 1., g.math('MAXIMUM', denominator, .001)))
    alpha = g.vector('DOT_PRODUCT', miter, tangent)
    leg = g.vector('DOT_PRODUCT', g.vector('SUBTRACT', bend, endpoint), tangent)
    residual = g.math('SUBTRACT', leg, mouth('trim'))
    plus = g.math('ADD', residual, g.math('MULTIPLY', g.math('ADD', offset, halfwidth), alpha))
    minus = g.math('ADD', residual, g.math('MULTIPLY', g.math('SUBTRACT', offset, halfwidth), alpha))
    side = g.switch(g.compare(plus, minus, 'LESS_THAN'), -1., 1.)
    minimum = g.math('MINIMUM', plus, minus)
    center_room = g.math('ADD', residual, g.math('MULTIPLY', offset, alpha))
    clearance = g.switch(g.compare(side, 0., 'GREATER_THAN'),
                          mouth('clearance_left'), mouth('clearance_right'))
    # A real clearance, proportional to road width, avoids fixing the report
    # with a numerically positive but effectively collapsed boundary edge.
    target = g.math('MAXIMUM', .05, g.math('MULTIPLY', .05, width))
    shift = g.math('SUBTRACT', target, minimum)
    blend = g.math('MINIMUM', g.math('MULTIPLY', .5, clearance),
                    g.math('MAXIMUM', halfwidth, g.math('MULTIPLY', 4., shift)))
    slope_scale = g.math('MULTIPLY', g.math('ABSOLUTE', alpha), halfwidth)
    eligible = g.all(
        g.compare(path_index, 0., 'GREATER_EQUAL'),
        g.compare(npoints, 3, 'GREATER_EQUAL', 'INT'), g.compare(npoints, 512, 'LESS_EQUAL', 'INT'),
        g.compare(first_off, npoints, 'LESS_THAN'),
        g.compare(bend_rank, 1., 'GREATER_EQUAL'),
        # The complementary strip map currently spans one retained interval.
        # Redundant controls swallowed by the junction are harmless; retained
        # controls between this mouth and the bend need a piecewise repair.
        g.compare(before_bend_station, g.math('ADD', mouth('trim'), 1e-5), 'LESS_EQUAL'),
        g.compare(mode, 0, kind='INT'), g.boolean('NOT', mouth('divided', 'BOOLEAN')),
        g.compare(denominator, .125, 'GREATER_EQUAL'),
        g.compare(minimum, 1e-4, 'LESS_EQUAL'), g.compare(center_room, target, 'GREATER_THAN'),
        g.compare(residual, .001, 'GREATER_THAN'),
        g.compare(shift, 0., 'GREATER_THAN'),
        g.compare(shift, g.math('MULTIPLY', .25, halfwidth), 'LESS_EQUAL'),
        g.compare(shift, g.math('MULTIPLY', .1, clearance), 'LESS_EQUAL'),
        # Monotone span lengths across the half-profile: delta*w' cannot
        # reverse their original slope, whose minimum remains at the edge.
        g.compare(shift, g.math('MULTIPLY', .5, slope_scale), 'LESS_EQUAL'),
        # Cubic smoothstep derivative <=1.5: junction Jacobian >=0.625.
        g.compare(blend, g.math('MULTIPLY', 4., shift), 'GREATER_EQUAL'))
    shift = g.switch(eligible, 0., shift)
    blend = g.switch(eligible, 0., blend)
    mouth_position = mouth('position', 'FLOAT_VECTOR')
    displacement = g.vector('SUBTRACT', position, mouth_position)
    axial = g.vector('DOT_PRODUCT', displacement, tangent)
    lateral = g.vector('DOT_PRODUCT', displacement, right)
    lateral_weight = _smoothstep(g, g.math('DIVIDE', g.math('MULTIPLY', side, lateral), halfwidth))
    axial_weight = _smoothstep(g, g.math('ADD', 1., g.math('DIVIDE', axial, g.math('MAXIMUM', blend, .001))))
    junction_id = g.sample(mouths, g.named('st_intersection_id'), iteration)
    same_junction = g.compare(g.named('st_intersection_id'), junction_id, kind='INT')
    inside = g.all(eligible, same_junction, g.compare(axial, 2e-5, 'LESS_EQUAL'),
                   g.compare(axial, g.math('MULTIPLY', -1., blend), 'GREATER_EQUAL'),
                   g.compare(g.math('ABSOLUTE', lateral), g.math('ADD', halfwidth, 2e-5), 'LESS_EQUAL'))
    amount = g.switch(inside, 0., g.math('MULTIPLY', shift, g.math('MULTIPLY', lateral_weight, axial_weight)))
    move = g.node('GeometryNodeSetPosition', 'Move only the straight inner-mouth collar along its Section')
    g.set(ri.outputs['Geometry'], move.inputs['Geometry'])
    g.set(g.vector('SCALE', tangent, g.math('MULTIPLY', -1., amount)), move.inputs['Offset'])
    # The analytic map is orientation-preserving.  Its discrete quads still
    # receive the standard four-corner test: coarse, skewed cells may require
    # a different layout even when the underlying continuous map is valid.
    # Inactive mouths feed empty geometry to the expensive check.
    local = g.node('GeometryNodeSeparateGeometry', 'Only the affected junction needs repair validation')
    local.domain = 'FACE'
    g.set(g.switch(eligible, None, move.outputs['Geometry'], 'GEOMETRY'), local.inputs['Geometry'])
    g.set(same_junction, local.inputs['Selection'])
    from .centerline_surface_nodes import _positive_quads
    positive = _positive_quads(g, local.outputs['Selection'], index, position)
    moved_boundary = g.all(inside, g.named('outer_boundary', 'BOOLEAN'),
                           g.compare(amount, 1e-7, 'GREATER_THAN'))
    boundary_safe = g.stat(g.switch(eligible, None, ri.outputs['Geometry'], 'GEOMETRY'), g.either(
        g.boolean('NOT', moved_boundary),
        g.close(lateral, g.math('MULTIPLY', side, halfwidth), 1e-4)))
    accepted = g.all(eligible, positive, boundary_safe)
    fields = {'shift': (g.switch(accepted, 0., shift), 'FLOAT'), 'side': (side, 'FLOAT'),
              'blend_length': (g.switch(accepted, 0., blend), 'FLOAT'),
              'residual': (residual, 'FLOAT'), 'adapted': (accepted, 'BOOLEAN')}
    enriched = ri.outputs['Mouths']
    for name, (value, kind) in fields.items():
        field = g.switch(g.compare(index, iteration, kind='INT'),
                         g.named('st_mouth_'+name, kind), value, kind)
        enriched = g.store(enriched, 'st_mouth_'+name, field, kind)
    g.set(enriched, ro.inputs['Mouths'])
    tagged = g.store(move.outputs['Geometry'], 'st_join_adapted',
                     g.either(g.named('st_join_adapted', 'BOOLEAN'), inside), 'BOOLEAN')
    g.set(g.switch(accepted, ri.outputs['Geometry'], tagged, 'GEOMETRY'), ro.inputs['Geometry'])
    return ro.outputs['Geometry'], ro.outputs['Mouths']
